def compute(vars):
    parent_value = vars["Year-end Net Asset Value"]
    x0 = vars["Total Assets"]
    total_liabilities = -parent_value + x0
    return {
        "value": total_liabilities,
        "trace": {
            "Year-end Net Asset Value": parent_value,
            "Total Assets": x0,
            "output_meta": {
                "currency": "$",
                "scale": "millions",
                "unit": None
            }
        }
    }
